  function toggleFrameEditor(open){const panel=$('#profileFramePanel');panel.hidden=!open;$('#settingsFrameOpen').setAttribute('aria-expanded',String(open));if(open){renderFrameEditor();panel.scrollIntoView({block:'nearest',behavior:'smooth'})}}
