  function selectProfilePhoto(event){const file=event.currentTarget.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/i.test(file.type||'')){event.currentTarget.value='';return toast('JPG, PNG, WebP 사진만 선택할 수 있습니다.')}if(file.size>cfg.MAX_IMAGE_BYTES){event.currentTarget.value='';return toast('프로필 사진은 12MB 이하만 선택할 수 있습니다.')}if(state.profilePhotoPreviewUrl)URL.revokeObjectURL(state.profilePhotoPreviewUrl);state.profilePhotoFile=file;state.profilePhotoRemove=false;state.profilePhotoPreviewUrl=URL.createObjectURL(file);renderProfilePhotoEditor()}
