  function previewDiaryFiles(){const chosen=[...($('#diaryImages').files||[])],existing=state.diaryEdit?.record_media?.length||0;if(existing+state.newDiaryFiles.length+chosen.length>6){$('#diaryImages').value='';return toast('일기 사진은 모두 합쳐 최대 6장까지 추가할 수 있어요.')}for(const f of chosen){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024){$('#diaryImages').value='';return toast('JPG, PNG, WebP 사진을 장당 10MB 이하로 선택해 주세요.')}}state.newDiaryFiles.push(...chosen.map(file=>({file,url:URL.createObjectURL(file)})));$('#diaryImages').value='';renderDiaryFiles()}
  function resetDiary(clearDraft=true){state.diaryEdit=null;clearDiaryFiles();$('#diaryDate').value=DB.today();$('#diaryMood').value='';$('#diaryTitle').value='';$('#diaryBody').value='';$('#diarySave').textContent='일기 저장';$('#diaryCancel').classList.add('hidden');$('#diaryDraftState').textContent='임시저장 준비';if(clearDraft&&DB.user())Drafts.del(diaryDraftKey()).catch(()=>{});renderDiaryFiles()}
  function diaryFilters(){return{query:$('#diarySearch').value,date:$('#diarySearchDate').value,mood:$('#diarySearchMood').value}}
  function renderDiary(){const all=state.records.filter(r=>r.category==='일상'),filters=diaryFilters(),active=Object.values(filters).some(Boolean),rows=Diary.filterRows(all,filters),pubs=publishedMap('diary');$('#diarySearchSummary').textContent=active?`검색 결과 ${rows.length}개`:`전체 ${all.length}개`;const host=$('#diaryList');host.innerHTML=rows.length?rows.map(r=>{const media=(r.record_media||[]).sort((a,b)=>a.sort_order-b.sort_order),pub=pubs.get(r.id);return `<article class="record-card"><div class="record-meta">${r.mood?`<span class="mood">${esc(r.mood)}</span>`:''}<span class="chip">${fmtDate(r.entry_date)}</span>${pub?'<span class="chip public">광장 공개</span>':''}</div><h3>${esc(r.title||'오늘의 일기')}</h3>${collapsibleCopy(r.body)}${media.length?`<div class="record-gallery">${media.map(m=>`<button data-lightbox="${esc(state.recordUrls.get(m.id)||'')}"><img src="${esc(state.recordUrls.get(m.id)||'')}" alt="${esc(m.original_name||'일기 사진')}" loading="lazy"></button>`).join('')}</div>`:''}<div class="record-actions"><button class="btn secondary small" data-edit-diary="${r.id}">수정</button><button class="btn secondary small" data-publish="diary:${r.id}">${pub?'공유 업데이트':'광장 공유'}</button>${pub?`<button class="btn ghost small" data-unpublish="diary:${r.id}">공유 취소</button>`:''}<button class="btn ghost small danger" data-delete-simple-record="${r.id}" data-return-page="diary">삭제</button></div></article>`}).join(''):`<div class="empty">${all.length&&active?'조건에 맞는 일기가 없습니다.':'아직 작성한 일기가 없습니다.'}</div>`;activateCollapsibleText(host)}
  function resetDiarySearch(){$('#diarySearch').value='';$('#diarySearchDate').value='';$('#diarySearchMood').value='';renderDiary();$('#diarySearch').focus()}
  async function loadDiary(){if(!$('#diaryDate').value)$('#diaryDate').value=DB.today();const rows=(await recordsForSimplePages()).filter(r=>r.category==='일상');await prepareRecordUrls(rows);renderDiary();await restoreDiaryDraft()}
  function startDiaryEdit(id){const r=state.records.find(x=>x.id===id);if(!r)return;state.diaryEdit=r;clearDiaryFiles();$('#diaryDate').value=r.entry_date;$('#diaryMood').value=r.mood||'';$('#diaryTitle').value=r.title||'';$('#diaryBody').value=r.body||'';$('#diarySave').textContent='수정 저장';$('#diaryCancel').classList.remove('hidden');$('#diaryDraftState').textContent='기존 일기 수정 중';renderDiaryFiles();$('#page-diary .simple-form').scrollIntoView({behavior:'smooth'})}
  async function saveDiary(){const body=$('#diaryBody').value.trim(),title=$('#diaryTitle').value.trim(),files=state.newDiaryFiles.map(x=>x.file),existing=state.diaryEdit?.record_media?.length||0;if(!body&&!title&&!files.length&&!existing)return toast('일기 내용이나 사진을 남겨 주세요.');const btn=$('#diarySave'),wasEdit=!!state.diaryEdit;setBusy(btn,true,files.length?'사진 업로드 중…':'저장 중…');let row=null;try{const payload={category:'일상',mood:$('#diaryMood').value,entry_date:$('#diaryDate').value||DB.today(),title,body,tags:['일기']};row=wasEdit?await withError(()=>DB.updateRecord(state.diaryEdit.id,payload),'일기 수정'):await withError(()=>DB.createRecord(payload),'일기 저장');if(files.length)await withError(()=>Storage.uploadRecordImages(row.id,files,existing),'일기 사진 업로드');resetDiary(true);await loadDiary();toast(wasEdit?'일기를 수정했습니다.':'일기를 저장했습니다.')}catch(e){if(row&&!wasEdit)toast('일기는 저장됐지만 사진 업로드를 마치지 못했습니다. 일기에서 다시 수정해 주세요.')}finally{setBusy(btn,false)}}
  async function removeDiaryMedia(id){const r=state.diaryEdit,m=r?.record_media?.find(x=>x.id===id);if(!m||!confirm('이 사진을 일기에서 삭제할까요?'))return;await withError(()=>Storage.removeRecordMedia(m),'일기 사진 삭제');await loadDiary();startDiaryEdit(r.id);toast('사진을 삭제했습니다.')}

  function bookMeta(record,prefix){return (record.tags||[]).find(t=>t.startsWith(`${prefix}:`))?.slice(prefix.length+1)||''}
  async function loadBooks(){const rows=(await recordsForSimplePages()).filter(r=>r.category==='독서');renderBooks(rows)}
  function renderBooks(source=state.records.filter(r=>r.category==='독서')){const q=$('#bookSearch').value.trim().toLowerCase(),rows=source.filter(r=>[r.title,r.body,(r.tags||[]).join(' ')].join(' ').toLowerCase().includes(q)).sort((a,b)=>String(b.entry_date).localeCompare(String(a.entry_date))),pubs=publishedMap('book'),host=$('#bookList');host.innerHTML=rows.length?rows.map(r=>{const author=bookMeta(r,'저자'),status=bookMeta(r,'상태'),rating=bookMeta(r,'평점'),pub=pubs.get(r.id);return `<article class="record-card"><div class="record-meta"><span class="chip">${esc(status||'독서')}</span><span class="muted">${esc(author||'저자 미입력')}</span>${pub?'<span class="chip public">광장 공개</span>':''}</div><h3>${esc(r.title||'제목 없는 책')}</h3>${rating?`<div class="book-rating">${'★'.repeat(Number(rating))}</div>`:''}${collapsibleCopy(r.body,'감상 없음')}<div class="record-actions"><button class="btn secondary small" data-edit-book="${r.id}">수정</button><button class="btn secondary small" data-publish="book:${r.id}">${pub?'공유 업데이트':'광장 공유'}</button>${pub?`<button class="btn ghost small" data-unpublish="book:${r.id}">공유 취소</button>`:''}<button class="btn ghost small danger" data-delete-simple-record="${r.id}" data-return-page="books">삭제</button></div></article>`}).join(''):'<div class="empty">조건에 맞는 독서록이 없습니다.</div>';activateCollapsibleText(host)}
  function resetBook(){state.bookEdit=null;$('#bookTitle').value='';$('#bookAuthor').value='';$('#bookNote').value='';$('#bookStatus').value='읽고 싶음';$('#bookRating').value='';$('#bookSave').textContent='독서록 저장';$('#bookCancel').classList.add('hidden')}
  function startBookEdit(id){const r=state.records.find(x=>x.id===id);if(!r)return;state.bookEdit=r;$('#bookTitle').value=r.title||'';$('#bookAuthor').value=bookMeta(r,'저자');$('#bookStatus').value=bookMeta(r,'상태')||'읽고 싶음';$('#bookRating').value=bookMeta(r,'평점');$('#bookNote').value=r.body||'';$('#bookSave').textContent='수정 저장';$('#bookCancel').classList.remove('hidden');$('#page-books .simple-form').scrollIntoView({behavior:'smooth'})}
  async function saveBook(){const title=$('#bookTitle').value.trim(),author=$('#bookAuthor').value.trim(),note=$('#bookNote').value.trim(),status=$('#bookStatus').value,rating=$('#bookRating').value;if(!title)return toast('책 제목을 입력해 주세요.');const btn=$('#bookSave'),wasEdit=!!state.bookEdit,payload={category:'독서',entry_date:state.bookEdit?.entry_date||DB.today(),title,body:note,tags:[`저자:${author||'미입력'}`,`상태:${status}`,...(rating?[`평점:${rating}`]:[])]};setBusy(btn,true,'저장 중…');try{if(wasEdit)await withError(()=>DB.updateRecord(state.bookEdit.id,payload),'독서록 수정');else await withError(()=>DB.createRecord(payload),'독서록 저장');resetBook();await loadBooks();toast(wasEdit?'독서록을 수정했습니다.':'독서록을 저장했습니다.')}finally{setBusy(btn,false)}}

  async function deleteSimpleRecord(id,returnPage){if(!confirm('이 항목과 첨부 파일을 삭제할까요?'))return;const r=state.records.find(x=>x.id===id),paths=(r?.record_media||[]).map(m=>m.storage_path);await withError(()=>DB.deleteRecord(id),'항목 삭제');if(paths.length)await Storage.removePrivatePaths(paths).catch(e=>console.warn('첨부 파일 정리 실패',e));if(returnPage==='diary')await loadDiary();else await loadBooks();toast('삭제했습니다.')}
  async function openRecordPage(id){await route('records');startRecordEdit(id);$('#recordComposer').scrollIntoView({behavior:'smooth'})}

  async function loadGlobalSearch(){const [records,events,ideas,finance]=await withError(()=>Promise.all([DB.listRecords(),DB.listEventsForMonth('2000-01-01','2100-12-31'),DB.listIdeas(),DB.listFinance()]),'통합 검색 준비');state.records=records;state.calendarEvents=events;state.ideas=ideas;state.finance=finance;renderGlobalSearch()}
  function renderGlobalSearch(){const q=$('#globalSearch').value.trim().toLowerCase(),host=$('#globalSearchResults');if(!q){host.innerHTML='<div class="empty">검색어를 입력하면 모든 개인 자료에서 찾아볼 수 있습니다.</div>';return}const rows=[];state.records.filter(x=>[x.title,x.body,(x.tags||[]).join(' ')].join(' ').toLowerCase().includes(q)).forEach(x=>rows.push({type:x.category==='일상'?'일기':x.category==='독서'?'독서록':'기록',title:x.title||'제목 없는 기록',body:x.body||'',page:x.category==='일상'?'diary':x.category==='독서'?'books':'records'}));state.calendarEvents.filter(x=>x.name?.toLowerCase().includes(q)).forEach(x=>rows.push({type:'캘린더',title:x.name,body:`${x.start_date} ~ ${x.end_date}`,page:'calendar'}));state.ideas.filter(x=>[x.title,x.body].join(' ').toLowerCase().includes(q)).forEach(x=>rows.push({type:'아이디어',title:x.title,body:x.body||'',page:'lab'}));state.finance.filter(x=>[x.title,x.category].join(' ').toLowerCase().includes(q)).forEach(x=>rows.push({type:'가계부',title:x.title,body:`${x.category} · ${money(x.amount)}`,page:'personal'}));host.innerHTML=rows.length?rows.slice(0,100).map(x=>`<button class="search-result" data-go="${x.page}"><span class="chip">${esc(x.type)}</span><strong>${esc(x.title)}</strong><small>${esc(x.body.slice(0,120))}</small></button>`).join(''):'<div class="empty">검색 결과가 없습니다.</div>'}

  function notificationKey(){return `lab:notifications-read:${DB.user()?.id||'guest'}`}
  async function loadNotifications(){const day=DB.today(),[data,todos,messages]=await withError(()=>Promise.all([DB.dashboard(day),DB.listTodos(day),DB.operatorMessages()]),'알림 불러오기'),read=localStorage.getItem(notificationKey())==='1',items=messages.map(x=>({id:x.id,title:x.title,body:x.body,read:x.read}));state.operatorUnread=messages.filter(x=>!x.read).map(x=>x.id);data.events.filter(e=>!e.done).forEach(e=>items.push({title:'오늘 일정',body:e.name}));const undone=todos.filter(x=>!x.completed);if(undone.length)items.push({title:'남은 할 일',body:`완료하지 않은 할 일이 ${undone.length}개 있습니다.`});$('#notificationList').innerHTML=items.length?items.map(x=>`<article class="notification-item ${(x.id?x.read:read)?'read':''}"><span></span><div><strong>${esc(x.title)}</strong><p>${esc(x.body)}</p></div></article>`).join(''):'<div class="empty">새로운 알림이 없습니다.</div>'}
  async function readAllNotifications(){try{await withError(()=>DB.readOperatorMessages(state.operatorUnread||[]),'알림 읽음 저장');localStorage.setItem(notificationKey(),'1');await loadNotifications();toast('알림을 모두 읽었습니다.')}catch{}}

  let contactOffset=0,contactGeneration=0;
  async function loadContacts(){
    const generation=++contactGeneration,host=$('#contactList');host.innerHTML='<p>문의 내역을 불러오는 중…</p>';
    try{const rows=await DB.myContacts(contactOffset);if(generation!==contactGeneration||state.page!=='contact')return;
      $('#contactPrev').disabled=contactOffset===0;$('#contactNext').disabled=rows.length<=20;
      host.innerHTML=rows.length?rows.slice(0,20).map(r=>`<article class="contact-ticket"><h3>${esc(r.title)}</h3><small>${esc(fmtTime(r.created_at))}</small><p class="body-text">${esc(r.body)}</p><button class="btn" data-contact-id="${esc(r.id)}">답변 보기</button><div class="contact-replies"></div></article>`).join(''):'<div class="empty">아직 보낸 문의가 없습니다.</div>';
    }catch{if(generation===contactGeneration)host.innerHTML='<p>문의를 불러오지 못했습니다. 새로고침으로 다시 시도하세요.</p>';}
  }
  async function contactReplies(button,offset=0){
    const host=button.parentElement.querySelector('.contact-replies');setBusy(button,true,'확인 중…');
    try{const rows=await DB.mySupportReplies(button.dataset.contactId,offset);if(!host.isConnected)return;
      host.innerHTML=rows.length?rows.slice(0,50).map(r=>`<div class="contact-reply"><strong>운영자 답변</strong><small>${esc(fmtTime(r.created_at))}</small><p class="body-text">${esc(r.body)}</p></div>`).join(''):'<p>아직 답변이 없습니다. 답변이 오면 알림함에서도 확인할 수 있습니다.</p>';
      for(const [label,next,enabled] of [['최근 답변',Math.max(0,offset-50),offset>0],['이전 답변',offset+50,rows.length>50]]){if(enabled){const b=document.createElement('button');b.className='btn';b.textContent=label;b.onclick=()=>contactReplies(button,next);host.append(b);}}
    }catch{host.textContent='답변을 불러오지 못했습니다. 답변 보기를 다시 눌러주세요.';}finally{setBusy(button,false);}
  }
  async function submitContact(e){e.preventDefault();const title=$('#contactTitle').value.trim(),body=$('#contactBody').value.trim();if(!title||!body)return toast('제목과 내용을 입력해 주세요.');const button=e.submitter;setBusy(button,true,'전송 중…');try{await withError(()=>DB.submitContact(title,body),'운영자 문의');$('#contactForm').reset();contactOffset=0;await loadContacts();toast('문의를 접수했습니다.');}catch{}finally{setBusy(button,false);}}
  async function submitBug(){const title=$('#bugTitle').value.trim(),body=$('#bugBody').value.trim(),screen=$('#bugScreen').value;if(!title||!body)return toast('문제 제목과 설명을 입력해 주세요.');const btn=$('#bugSubmit');setBusy(btn,true,'전송 중…');try{await withError(()=>DB.submitBugReport(title,body,screen),'버그 제보');$('#bugTitle').value='';$('#bugBody').value='';toast('버그 제보를 접수했습니다.')}finally{setBusy(btn,false)}}

  function draftPayload(){return{category:'생각',mood:'',entry_date:$('#recordDate').value||DB.today(),title:'',body:$('#recordBody').value,tags:$('#recordTags').value,edit_id:state.recordEdit?.id||null,updated_at:Date.now()}}
  function scheduleDraft(){clearTimeout(state.draftTimer);$('#draftState').textContent='임시저장 중…';state.draftTimer=setTimeout(async()=>{try{await Drafts.set(`record:${DB.user().id}`,draftPayload());$('#draftState').textContent='이 기기에 임시저장됨'}catch{$('#draftState').textContent='임시저장 실패'}},650)}
  async function restoreDraft(){try{const d=await Drafts.get(`record:${DB.user().id}`);if(!d||state.recordEdit||(!d.body&&!d.tags))return;if(!$('#recordBody').value){$('#recordDate').value=d.entry_date||DB.today();$('#recordBody').value=d.body||'';$('#recordTags').value=d.tags||'';$('#draftState').textContent='이전 임시저장을 복원했습니다.'}}catch{}}
  function clearPreviewUrls(){state.newRecordFiles.forEach(x=>{if(x.url)URL.revokeObjectURL(x.url)});state.newRecordFiles=[]}
  function renderNewRecordFiles(){const host=$('#recordPhotoPreview');host.innerHTML=state.newRecordFiles.map((x,i)=>`<div class="photo-thumb"><img src="${esc(x.url)}" alt="새 사진 ${i+1}"><button data-remove-new-photo="${i}" aria-label="사진 제거">×</button></div>`).join('')}
  function previewRecordFiles(){const files=[...$('#recordImages').files];if(state.newRecordFiles.length+files.length>cfg.RECORD_IMAGE_LIMIT){toast(`사진은 최대 ${cfg.RECORD_IMAGE_LIMIT}장까지 선택할 수 있어요.`);$('#recordImages').value='';return}if(files.some(f=>f.size>cfg.MAX_IMAGE_BYTES)){toast('12MB를 넘는 사진이 있습니다.');$('#recordImages').value='';return}state.newRecordFiles=[...state.newRecordFiles,...files.map(file=>({file,url:URL.createObjectURL(file)}))];$('#recordImages').value='';renderNewRecordFiles()}
  function resetRecordComposer(clearDraft=true){state.recordEdit=null;clearPreviewUrls();$('#recordImages').value='';$('#recordDate').value=DB.today();$('#recordBody').value='';$('#recordTags').value='';$('#recordComposerTitle').textContent='새 기록';$('#recordCancelEdit').classList.add('hidden');$('#recordSave').textContent='저장';$('#draftState').textContent='임시저장 준비';if(clearDraft&&DB.user())Drafts.del(`record:${DB.user().id}`).catch(()=>{});renderNewRecordFiles()}
  async function loadRecords(){
    if(!$('#recordDate').value)$('#recordDate').value=DB.today();const records=await withError(()=>DB.listRecords(),'기록 불러오기');state.records=records;state.ownPublications=cfg.COMMUNITY_ENABLED?await DB.listOwnPublications().catch(()=>[]):[];await prepareRecordUrls(records);renderRecords();await restoreDraft();
  }
  async function prepareRecordUrls(records){state.recordUrls.clear();const jobs=[];for(const r of records){for(const m of (r.record_media||[]).slice(0,6)){jobs.push(Storage.signedPrivate(m.storage_path,3600).then(url=>state.recordUrls.set(m.id,url)).catch(()=>state.recordUrls.set(m.id,'')))}}await Promise.all(jobs)}
  function publishedMap(type){return new Map(state.ownPublications.filter(p=>p.source_type===type).map(p=>[p.source_id,p]))}
  function favoriteKey(){return `lab:favorites:${DB.user()?.id||'guest'}`}
  function favoriteIds(){try{return new Set(JSON.parse(localStorage.getItem(favoriteKey())||'[]'))}catch{return new Set()}}
  function toggleFavorite(id){const ids=favoriteIds();ids.has(id)?ids.delete(id):ids.add(id);localStorage.setItem(favoriteKey(),JSON.stringify([...ids]));renderRecords()}
  function renderRecords(){
    const q=$('#recordSearch').value.trim().toLowerCase(),filter=$('#recordFilter').value,sort=$('#recordSort')?.value||'newest',pubs=publishedMap('record'),favs=favoriteIds();let rows=state.records.filter(r=>r.category!=='일상'&&r.category!=='독서').filter(r=>(filter!=='즐겨찾기'||favs.has(r.id))&&(!q||[r.body,(r.tags||[]).join(' ')].join(' ').toLowerCase().includes(q)));rows.sort((a,b)=>sort==='oldest'?String(a.entry_date).localeCompare(String(b.entry_date))||String(a.created_at).localeCompare(String(b.created_at)):String(b.entry_date).localeCompare(String(a.entry_date))||String(b.created_at).localeCompare(String(a.created_at)));
    const host=$('#recordList');host.innerHTML=rows.length?rows.map(r=>{const media=(r.record_media||[]).sort((a,b)=>a.sort_order-b.sort_order),pub=pubs.get(r.id),fav=favs.has(r.id);return `<article class="record-card"><div class="record-meta"><span class="muted">${fmtDate(r.entry_date)}</span><button class="link-btn ${fav?'on':''}" data-favorite-record="${r.id}" aria-label="즐겨찾기">${fav?'★':'☆'}</button>${pub?`<span class="chip ${pub.audience}">${pub.audience==='public'?'광장 공개':'팔로워 공개'}</span>`:''}</div>${collapsibleCopy(r.body)}${r.tags?.length?`<div class="row wrap" style="margin-top:10px">${r.tags.map(t=>`<span class="chip">#${esc(t)}</span>`).join('')}</div>`:''}${media.length?`<div class="record-gallery">${media.map(m=>`<button data-lightbox="${esc(state.recordUrls.get(m.id)||'')}"><img src="${esc(state.recordUrls.get(m.id)||'')}" alt="${esc(m.original_name||'기록 사진')}" loading="lazy"></button>`).join('')}</div>`:''}<div class="record-actions"><button class="btn secondary small" data-edit-record="${r.id}">수정</button><button class="btn secondary small" data-publish="record:${r.id}">${pub?'공유 업데이트':'광장 공유'}</button>${pub?`<button class="btn ghost small" data-unpublish="record:${r.id}">공유 취소</button>`:''}<button class="btn ghost small danger" data-delete-record="${r.id}">삭제</button></div></article>`}).join(''):'<div class="empty">조건에 맞는 기록이 없습니다.</div>';activateCollapsibleText(host);
  }
  function startRecordEdit(id){const r=state.records.find(x=>x.id===id);if(!r||r.category==='일상'||r.category==='독서')return;state.recordEdit=r;clearPreviewUrls();$('#recordComposerTitle').textContent='기록 수정';$('#recordCancelEdit').classList.remove('hidden');$('#recordSave').textContent='수정 저장';$('#recordDate').value=r.entry_date;$('#recordBody').value=r.body||'';$('#recordTags').value=(r.tags||[]).join(', ');renderNewRecordFiles();$('#recordComposer').scrollIntoView({behavior:'smooth',block:'start'})}
  async function moveExistingMedia(id,direction){const r=state.recordEdit;if(!r)return;const ordered=[...(r.record_media||[])].sort((a,b)=>a.sort_order-b.sort_order),i=ordered.findIndex(x=>x.id===id),j=direction==='up'?i-1:i+1;if(i<0||j<0||j>=ordered.length)return;[ordered[i],ordered[j]]=[ordered[j],ordered[i]];await withError(()=>DB.reorderRecordMedia(r.id,ordered.map(x=>x.id)),'사진 순서 저장');await loadRecords();startRecordEdit(r.id);toast('사진 순서를 저장했습니다.')}
  async function saveRecord(){
    const payload=draftPayload(),files=state.newRecordFiles.map(x=>x.file),btn=$('#recordSave'),wasEdit=!!state.recordEdit,existingCount=state.recordEdit?.record_media?.length||0;if(!payload.body.trim()&&!files.length&&!existingCount)return toast('내용 또는 사진을 남겨 주세요.');setBusy(btn,true,files.length?'사진 업로드 중…':'저장 중…');
    let row=null;try{row=wasEdit?await withError(()=>DB.updateRecord(state.recordEdit.id,payload),'기록 수정'):await withError(()=>DB.createRecord(payload),'기록 저장');if(files.length)await withError(()=>Storage.uploadRecordImages(row.id,files,existingCount),'사진 업로드');resetRecordComposer(true);await loadRecords();toast(wasEdit?'기록을 수정했습니다.':'기록을 저장했습니다.')}catch(e){if(row&&!wasEdit)toast('글은 저장되었지만 사진 처리 중 문제가 생겼습니다. 기록 목록에서 다시 편집할 수 있어요.')}finally{setBusy(btn,false)}
  }
  async function removeExistingMedia(id){const r=state.recordEdit,m=r?.record_media?.find(x=>x.id===id);if(!m)return;if(!confirm('이 사진을 기록에서 삭제할까요?'))return;await withError(()=>Storage.removeRecordMedia(m),'사진 삭제');await loadRecords();startRecordEdit(r.id);toast('사진을 삭제했습니다.')}
  async function deleteRecord(id){if(!confirm('이 기록과 첨부 사진을 삭제할까요?'))return;const r=state.records.find(x=>x.id===id),paths=(r?.record_media||[]).map(m=>m.storage_path);try{await withError(()=>DB.deleteRecord(id),'기록 삭제');let cleanupFailed=false;if(paths.length)try{await Storage.removePrivatePaths(paths)}catch(e){cleanupFailed=true;console.warn(e)}await loadRecords();toast(cleanupFailed?'기록은 삭제됐고, 일부 파일 정리는 다음 점검에서 다시 확인합니다.':'기록을 삭제했습니다.')}catch{}}

  function monthBounds(view){const start=new Date(view.getFullYear(),view.getMonth(),1),end=new Date(view.getFullYear(),view.getMonth()+1,0);return[dateKey(start),dateKey(end)]}
  function calendarGridBounds(view){const first=new Date(view.getFullYear(),view.getMonth(),1),start=new Date(first);start.setDate(1-first.getDay());const end=new Date(start);end.setDate(start.getDate()+41);return[dateKey(start),dateKey(end)]}
  async function loadCalendar(){const [gridStart,gridEnd]=calendarGridBounds(state.calendarView);const [events,habits,checks,records]=await withError(()=>Promise.all([DB.listEventsForMonth(gridStart,gridEnd),DB.listHabits(),DB.checksForRange(shiftDay(gridStart,-6),gridEnd),DB.listRecords()]),'캘린더 불러오기');state.calendarEvents=events;state.habits=habits;state.habitChecks=checks;state.records=records;renderCalendar();renderSelectedDay()}
  function moveCalendar(n){state.calendarView.setMonth(state.calendarView.getMonth()+n);state.calendarView.setDate(1);state.selectedDay=new Date(state.calendarView);loadCalendar().catch(()=>{})}
  function moodClass(value=''){if(value.includes('좋음'))return'good';if(value.includes('평온'))return'calm';if(value.includes('슬픔')||value.includes('아쉬움'))return'sad';if(value.includes('힘듦'))return'hard';return value?'normal':''}
  function renderCalendar(){
    const v=state.calendarView,first=new Date(v.getFullYear(),v.getMonth(),1),offset=first.getDay(),start=new Date(v.getFullYear(),v.getMonth(),1-offset),gridStart=dateKey(start),today=DB.today(),moods=new Map(),calendarItems=[...state.calendarEvents,...Cal.holidayEvents(gridStart,42)],layout=Cal.buildEventLayout(calendarItems,gridStart,42,2);
    state.records.filter(r=>r.category==='일상'&&r.mood).sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at))).forEach(r=>moods.set(r.entry_date,r.mood));
    $('#calendarMonth').textContent=`${v.getFullYear()}년 ${v.getMonth()+1}월`;
    let out='';
    for(let i=0;i<42;i++){
      const d=new Date(start);d.setDate(start.getDate()+i);
      const k=dateKey(d),outside=d.getMonth()!==v.getMonth(),events=state.calendarEvents.filter(e=>e.start_date<=k&&e.end_date>=k),mood=moods.get(k),holiday=Cal.holidayFor(k),cell=layout.get(k),marker=Cal.habitMarker(k,state.habits,state.habitChecks),important=events.some(e=>e.important&&e.start_date===k);
      const eventHtml=(cell?.slots||[]).map(slot=>{
        if(!slot)return'<span class="day-event-slot" aria-hidden="true"></span>';
        const e=slot.event,color=Cal.sanitizeColor(e.color_key),label=slot.start||e.start_date===e.end_date?`${e.important?'★ ':''}${esc(e.name)}`:'';
        return `<span class="day-event color-${color} ${e.system?'system-event':''} ${slot.start?'range-start':''} ${slot.end?'range-end':''} ${!slot.start&&!slot.end?'range-mid':''}" title="${esc(e.name)}"><span>${label}</span></span>`;
      }).join('');
      out+=`<button class="day ${outside?'outside':''} ${k===today?'today':''} ${k===dateKey(state.selectedDay)?'selected':''} ${important?'important-date':''} ${d.getDay()===0?'sunday':''} ${d.getDay()===6?'saturday':''} ${holiday?'holiday':''}" data-select-day="${k}" aria-label="${fmtDate(k)}${holiday?`, ${holiday}`:''}"><span class="day-number">${d.getDate()}</span>${mood?`<span class="day-mood mood-${moodClass(mood)}" title="기분: ${esc(mood)}"></span>`:''}<div class="day-events">${eventHtml}${cell?.hidden?`<span class="day-more">+${cell.hidden}</span>`:''}</div>${marker?`<span class="day-habit-status ${marker}" title="${marker==='complete'?'체크리스트 완료':'오늘 남은 체크리스트 있음'}">${marker==='complete'?'<svg class="habit-check-icon" viewBox="0 0 16 16" aria-hidden="true"><path d="M2.5 8.5 6.3 12 13.5 4"/></svg>':''}</span>`:''}</button>`;
    }
    $('#calendarDays').innerHTML=out;
  }
  function checksMapFor(day){return new Map(state.habitChecks.filter(c=>c.day===day).map(c=>[c.habit_id,c.completed]))}
  const habitScheduleLabel=s=>s?.type==='weekdays'?'평일':s?.type==='selected_weekdays'?`선택 요일 ${(s.days||[]).map(d=>['일','월','화','수','목','금','토'][d]).join('·')}`:s?.type==='weekly_n'?`주 ${s.count||1}회`:'매일';
  function habitScheduleValue(){const type=$('#habitSchedule').value,start_date=state.habitEdit?(state.habitEdit.schedule?.start_date||Cal.habitStartDay(state.habitEdit)):DB.today();if(type==='weekly_n')return{type,count:clamp(Number($('#habitWeeklyCount').value)||1,1,7),start_date};if(type==='selected_weekdays'){const days=$$('#habitWeekdayPicker input:checked').map(x=>Number(x.value));return{type,days:days.length?days:[1],start_date}}return{type,start_date}}
  function resetHabitEditor(){state.habitEdit=null;$('#habitNewName').value='';$('#habitSchedule').value='daily';$('#habitWeeklyCount').value='3';$('#habitWeeklyCountWrap').classList.add('hidden');$('#habitWeekdayPicker').classList.add('hidden');$$('#habitWeekdayPicker input').forEach(x=>x.checked=false);$('#habitAdd').textContent='추가';$('#habitCancel').classList.add('hidden')}
  function startHabitEdit(id){const h=state.habits.find(x=>x.id===id);if(!h)return;state.habitEdit=h;$('#habitNewName').value=h.name;$('#habitSchedule').value=h.schedule?.type||'daily';$('#habitWeeklyCount').value=h.schedule?.count||3;$('#habitWeeklyCountWrap').classList.toggle('hidden',$('#habitSchedule').value!=='weekly_n');$('#habitWeekdayPicker').classList.toggle('hidden',$('#habitSchedule').value!=='selected_weekdays');$$('#habitWeekdayPicker input').forEach(x=>x.checked=(h.schedule?.days||[]).includes(Number(x.value)));$('#habitAdd').textContent='수정 저장';$('#habitCancel').classList.remove('hidden');$('#habitNewName').focus()}
  function renderSelectedDay(){
    const day=dateKey(state.selectedDay),userEvents=state.calendarEvents.filter(e=>e.start_date<=day&&e.end_date>=day),holiday=Cal.holidayFor(day),events=[...(holiday?[{id:`holiday:${day}`,name:holiday,start_date:day,end_date:day,color_key:'rose',system:true,holiday:true}]:[]),...userEvents],checks=checksMapFor(day),holidayEl=$('#selectedHoliday');
    $('#selectedDayTitle').textContent=fmtDate(day);
    holidayEl.textContent='';holidayEl.classList.add('hidden');
    if(!state.eventEdit){$('#eventStart').value=day;$('#eventEnd').value=day}
    $('#selectedEvents').innerHTML=events.length?events.map(e=>{const color=Cal.sanitizeColor(e.color_key);if(e.system)return `<div class="event-row system-row"><span class="event-color-dot color-${color}" aria-hidden="true"></span><div class="event-copy"><strong>${esc(e.name)}</strong><span>대한민국 공휴일</span></div></div>`;return `<div class="event-row"><span class="event-color-dot color-${color}" aria-hidden="true"></span><button class="check ${e.done?'done':''}" data-event-toggle="${e.id}" data-done="${e.done}">${e.done?'✓':''}</button><div class="event-copy"><strong>${e.important?'<span class="important-star">★</span> ':''}${esc(e.name)}</strong><span>${fmtShort(e.start_date)}${e.end_date!==e.start_date?` ~ ${fmtShort(e.end_date)}`:''}</span></div>${!e.done?`<button class="link-btn" data-move-event="${e.id}" data-event-start="${e.start_date}" data-event-end="${e.end_date}" data-event-name="${esc(e.name)}" data-event-important="${!!e.important}" data-event-color="${color}">다음 날</button>`:''}<button class="link-btn" data-edit-event="${e.id}">수정</button><button aria-label="일정 삭제" data-delete-event="${e.id}">×</button></div>`}).join(''):'<div class="empty">이 날짜에는 일정이 없습니다.</div>';
    const runnable=state.habits.filter(h=>Cal.habitRunsOn(day,h,state.habitChecks,{includeBeforeStart:day<DB.today()}));
    $('#selectedHabits').innerHTML=runnable.length?runnable.map(h=>{const progress=h.schedule?.type==='weekly_n'?Cal.weeklyProgress(h,day,state.habitChecks,day):null,label=progress?`이번 주 ${progress.completed}/${progress.target} · 월요일에 다시 시작`:habitScheduleLabel(h.schedule);return `<div class="mini-item"><button class="check ${checks.get(h.id)?'done':''}" data-habit-toggle="${h.id}" data-day="${day}" aria-label="${esc(h.name)} 체크"><span>${checks.get(h.id)?'✓':''}</span></button><div class="body"><strong>${esc(h.name)}</strong><span>${esc(label)}</span></div></div>`}).join(''):'<div class="empty">이 날짜에 예정된 체크리스트가 없습니다.</div>';
    $('#habitTemplateList').innerHTML=state.habits.map(h=>`<div class="habit-setting-row"><div><strong>${esc(h.name)}</strong><small>${esc(habitScheduleLabel(h.schedule))}</small></div><span class="spacer"></span><button class="link-btn" data-edit-habit="${h.id}">수정</button><button class="link-btn danger" data-delete-habit="${h.id}">삭제</button></div>`).join('')||'<div class="empty compact">설정한 항목이 없습니다.</div>';
  }
  function shiftDay(day,amount=1){const d=new Date(`${day}T12:00:00`);d.setDate(d.getDate()+amount);return dateKey(d)}
  async function moveEventNext(button){const important=button.dataset.eventImportant==='true',color=button.dataset.eventColor||'forest';await withError(()=>DB.updateEvent(button.dataset.moveEvent,button.dataset.eventName,shiftDay(button.dataset.eventStart),shiftDay(button.dataset.eventEnd),important,color),'일정 넘기기');toast('일정을 다음 날로 넘겼습니다.');if(state.page==='today')await loadToday();else await loadCalendar()}
  function renderGoalInputs(){const f=state.goals.find(g=>g.kind==='final'),m=state.goals.find(g=>g.kind==='monthly');$('#finalGoalInput').value=f?.title||'';$('#finalGoalReason').value=f?.note||'';$('#finalGoalDeadline').value=f?.deadline||'';$('#monthlyGoalInput').value=m?.title||'';$('#monthlyGoalAction').value=m?.note||''}
  async function loadGoalsPage(){state.goals=await withError(()=>DB.loadGoals(new Date()),'목표 불러오기');renderGoalInputs()}
  const selectedEventColor=()=>Cal.sanitizeColor($('input[name="eventColor"]:checked')?.value);
  function setEventColor(value='forest'){$$('input[name="eventColor"]').forEach(input=>input.checked=input.value===Cal.sanitizeColor(value))}
  async function addEvent(){const name=$('#eventName').value.trim(),start=$('#eventStart').value,end=$('#eventEnd').value||start,important=$('#eventImportant').checked,color=selectedEventColor();if(!name)return toast('일정 내용을 입력해 주세요.');if(!start||!end||end<start)return toast('일정 날짜 범위를 확인해 주세요.');if(state.eventEdit){await withError(()=>DB.updateEvent(state.eventEdit.id,name,start,end,important,color),'일정 수정');state.eventEdit=null;$('#eventAdd').textContent='일정 추가';$('#eventCancel').classList.add('hidden');toast('일정을 수정했습니다.')}else{await withError(()=>DB.addEvent(name,start,end,important,color),'일정 추가');toast('일정을 추가했습니다.')}$('#eventName').value='';$('#eventImportant').checked=false;setEventColor();await loadCalendar()}
  function startEventEdit(id){const e=state.calendarEvents.find(x=>x.id===id);if(!e)return;state.eventEdit=e;$('#eventName').value=e.name;$('#eventStart').value=e.start_date;$('#eventEnd').value=e.end_date;$('#eventImportant').checked=!!e.important;setEventColor(e.color_key);$('#eventAdd').textContent='일정 수정';$('#eventCancel').classList.remove('hidden');$('#eventName').focus()}
  function cancelEventEdit(){state.eventEdit=null;$('#eventName').value='';$('#eventImportant').checked=false;setEventColor();$('#eventAdd').textContent='일정 추가';$('#eventCancel').classList.add('hidden');renderSelectedDay()}
  async function toggleEvent(id,done){await withError(()=>DB.toggleEvent(id,!done),'일정 체크');if(state.page==='today')await loadToday();else await loadCalendar()}
  async function toggleHabit(id,day){const current=state.page==='today'?null:checksMapFor(day).get(id);let done=current;if(state.page==='today'){const d=await DB.dashboard(day);done=new Map(d.checks.map(c=>[c.habit_id,c.completed])).get(id)}await withError(()=>DB.setHabitCheck(id,day,!done),'체크 저장');if(state.page==='today')await loadToday();else await loadCalendar()}
  async function saveGoals(){await withError(()=>DB.saveGoals($('#finalGoalInput').value.trim(),$('#finalGoalDeadline').value,$('#monthlyGoalInput').value.trim(),new Date(),$('#finalGoalReason').value.trim(),$('#monthlyGoalAction').value.trim()),'목표 저장');await loadGoalsPage();toast('목표를 저장했습니다.')}

  async function loadLab(){const [projects,ideas,works,finance]=await withError(()=>Promise.all([DB.listProjects(),DB.listIdeas(),DB.listWorks(),DB.listFinance()]),'내 공간 불러오기');state.projects=projects;state.ideas=ideas;state.works=works;state.finance=finance;state.ownPublications=cfg.COMMUNITY_ENABLED?await DB.listOwnPublications().catch(()=>[]):[];await prepareIdeaUrls(ideas);renderLabTabs();renderProjects();renderIdeas();await renderWorks();renderFinance();renderAllLab()}
  function switchLabTab(tab){state.labTab=tab;renderLabTabs();if(state.page!=='lab')route('lab').catch(()=>{})}
  function renderLabTabs(){$$('#labTabs [data-module]').forEach(b=>b.classList.toggle('active',b.dataset.module===state.labTab));$$('#page-lab .module-pane').forEach(p=>p.classList.toggle('active',p.id===`module-${state.labTab}`));if(state.page==='personal')$('#module-finance')?.classList.add('active')}
  function renderAllLab(){const q=$('#labSearch')?.value.trim();if(!$('#labSearchResults'))return;const p=state.projects.filter(x=>labMatches(x,['title','summary'])).map(x=>`<article class="project-card"><span class="chip">프로젝트</span><h3>${esc(x.title)}</h3><p>${esc(x.summary||'')}</p><button class="btn secondary small" data-open-project="${x.id}">열기</button></article>`);const i=state.ideas.filter(x=>labMatches(x,['title','body','next_step'])).map(x=>`<article class="idea-card"><span class="chip">아이디어</span><h3>${esc(x.title)}</h3><p>${esc(x.body||'')}</p></article>`);const w=state.works.filter(x=>labMatches(x,['title','description','category'])).map(x=>`<article class="work-card"><span class="chip">작업물</span><h3>${esc(x.title)}</h3><p>${esc(x.description||'')}</p></article>`);$('#labSearchResults').innerHTML=p.concat(i,w).join('')||`<div class="empty">${q?'검색 결과가 없습니다.':'프로젝트·아이디어·작업물을 한눈에 볼 수 있습니다.'}</div>`}
  const labMatches=(x,fields)=>{const q=$('#labSearch')?.value.trim().toLowerCase();return !q||fields.some(k=>String(x?.[k]||'').toLowerCase().includes(q))};
  function renderProjects(){const rows=state.projects.filter(p=>labMatches(p,['title','summary','problem','result','learning']));$('#projectList').innerHTML=rows.length?rows.map(p=>`<article class="project-card"><div class="row"><span class="chip">${statusLabel(p.status)}</span><span class="spacer"></span></div><div class="project-kicker">PROJECT</div><h3>${esc(p.title)}</h3><p>${esc(p.summary||'프로젝트 설명을 추가해 보세요.')}</p><div class="record-actions"><button class="btn secondary small" data-open-project="${p.id}">상세 편집</button></div></article>`).join(''):'<div class="empty">조건에 맞는 프로젝트가 없습니다.</div>'}
  async function addProject(){const title=$('#projectTitle').value.trim();if(!title)return toast('프로젝트 이름을 입력해 주세요.');await withError(()=>DB.addProject({title,summary:$('#projectSummary').value.trim(),status:$('#projectStatus').value,progress:0}),'프로젝트 만들기');$('#projectTitle').value='';$('#projectSummary').value='';await loadLab();toast('프로젝트를 만들었습니다.')}
  function openProject(id){const p=state.projects.find(x=>x.id===id);if(!p)return;state.projectEdit=p;$('#projectModalTitle').textContent=p.title;$('#pdSummary').value=p.summary||'';$('#pdRole').value=p.role||'';$('#pdPeriod').value=p.period||'';$('#pdType').value=p.project_type||'';$('#pdContribution').value=p.contribution||'';$('#pdProblem').value=p.problem||'';$('#pdProcess').value=p.process||'';$('#pdResult').value=p.result||'';$('#pdLearning').value=p.learning||'';$('#pdSkills').value=(p.skills||[]).join(', ');$('#pdStatus').value=p.status;openModal('projectModal')}
  async function saveProjectDetail(){const p=state.projectEdit;if(!p)return;const btn=$('#projectDetailSave');setBusy(btn,true,'저장 중…');try{await withError(()=>DB.updateProject(p.id,{summary:$('#pdSummary').value.trim(),role:$('#pdRole').value.trim(),period:$('#pdPeriod').value.trim(),project_type:$('#pdType').value.trim(),contribution:$('#pdContribution').value.trim(),problem:$('#pdProblem').value.trim(),process:$('#pdProcess').value.trim(),result:$('#pdResult').value.trim(),learning:$('#pdLearning').value.trim(),skills:$('#pdSkills').value.trim(),status:$('#pdStatus').value}),'프로젝트 저장');await uploadPendingProjectFiles(p);dismissModal('projectModal');await loadLab();toast('프로젝트를 저장했습니다.')}finally{setBusy(btn,false)}}
  async function prepareIdeaUrls(ideas){state.ideaUrls.clear();const jobs=[];for(const idea of ideas){for(const media of (idea.idea_media||[]).slice(0,cfg.RECORD_IMAGE_LIMIT)){jobs.push(Storage.signedPrivate(media.storage_path,3600).then(url=>state.ideaUrls.set(media.id,url)).catch(()=>state.ideaUrls.set(media.id,'')))}}await Promise.all(jobs)}
  function renderIdeaFiles(){const host=$('#ideaPhotoPreview');host.innerHTML=state.newIdeaFiles.map((item,index)=>`<div class="photo-thumb"><img src="${esc(item.url)}" alt="새 아이디어 사진 ${index+1}"><button data-remove-new-idea-photo="${index}" aria-label="사진 제외">×</button></div>`).join('')}
  function previewIdeaFiles(){const input=$('#ideaImages'),files=[...input.files];if(state.newIdeaFiles.length+files.length>cfg.RECORD_IMAGE_LIMIT){toast(`사진은 최대 ${cfg.RECORD_IMAGE_LIMIT}장까지 선택할 수 있어요.`);input.value='';return}if(files.some(file=>file.size>cfg.MAX_IMAGE_BYTES)){toast('12MB를 넘는 사진이 있습니다.');input.value='';return}if(files.some(file=>!/^image\/(jpeg|png|webp)$/i.test(file.type||''))){toast('JPG, PNG, WebP 사진만 추가할 수 있어요.');input.value='';return}state.newIdeaFiles.push(...files.map(file=>({file,url:URL.createObjectURL(file)})));input.value='';renderIdeaFiles()}
  function clearIdeaFiles(){state.newIdeaFiles.forEach(item=>URL.revokeObjectURL(item.url));state.newIdeaFiles=[];$('#ideaImages').value='';renderIdeaFiles()}
  function renderIdeas(){const rows=state.ideas.filter(i=>labMatches(i,['title','body'])),host=$('#ideaList');host.innerHTML=rows.length?rows.map(i=>{const media=(i.idea_media||[]).sort((a,b)=>a.sort_order-b.sort_order);return `<article class="idea-card"><div class="row"><span class="chip">아이디어</span><span class="spacer"></span><button class="link-btn danger" data-delete-idea="${i.id}">삭제</button></div><h3>${esc(i.title)}</h3>${collapsibleCopy(i.body,'간단한 아이디어')}${media.length?`<div class="record-gallery">${media.map(m=>`<button data-lightbox="${esc(state.ideaUrls.get(m.id)||'')}"><img src="${esc(state.ideaUrls.get(m.id)||'')}" alt="${esc(m.original_name||'아이디어 사진')}" loading="lazy"></button>`).join('')}</div>`:''}</article>`}).join(''):'<div class="empty">저장한 아이디어가 없습니다.</div>';activateCollapsibleText(host)}
  async function addIdea(){const title=$('#ideaTitle').value.trim(),files=state.newIdeaFiles.map(item=>item.file),button=$('#ideaAdd');if(!title)return toast('아이디어 제목을 입력해 주세요.');setBusy(button,true,files.length?'사진 업로드 중…':'저장 중…');let row=null;try{row=await withError(()=>DB.addIdea({title,body:$('#ideaBody').value.trim(),next_step:$('#ideaNext').value.trim()}),'아이디어 저장');if(files.length)await withError(()=>Storage.uploadIdeaImages(row.id,files),'아이디어 사진 업로드');$('#ideaTitle').value='';$('#ideaBody').value='';$('#ideaNext').value='';clearIdeaFiles();await loadLab();toast('아이디어를 저장했습니다.')}catch(error){if(row){await DB.deleteIdea(row.id).catch(()=>{});toast('사진 저장을 마치지 못해 아이디어 저장을 취소했습니다. 다시 시도해 주세요.')}throw error}finally{setBusy(button,false)}}
  async function deleteIdea(id){const idea=state.ideas.find(item=>item.id===id),paths=(idea?.idea_media||[]).map(media=>media.storage_path).filter(Boolean);await withError(()=>DB.deleteIdea(id),'아이디어 삭제');let cleanupFailed=false;if(paths.length)try{await Storage.removePrivatePaths(paths)}catch(error){cleanupFailed=true;console.warn(error)}await loadLab();toast(cleanupFailed?'아이디어는 삭제됐고 사진 파일 정리는 다음 점검에서 다시 확인합니다.':'아이디어를 삭제했습니다.')}
  async function convertIdea(id){await withError(()=>DB.convertIdea(id),'프로젝트 전환');state.labTab='projects';await loadLab();toast('프로젝트로 전환했습니다.')}
  async function renderWorks(){const cards=[];for(const w of state.works.filter(x=>labMatches(x,['title','description','category']))){let download='';if(w.file_path){download=`<button class="btn secondary small" data-download-work="${w.id}">파일 다운로드</button>`}cards.push(`<article class="work-card"><div class="row"><span class="chip">${esc(w.category)}</span><span class="spacer"></span><button class="link-btn" data-edit-work="${w.id}">수정</button><button class="link-btn danger" data-delete-work="${w.id}">삭제</button></div><h3>${esc(w.title)}</h3><p>${esc(w.description||'설명 없음')}</p><div class="record-actions">${download}${w.link&&safeUrl(w.link)?`<a class="btn secondary small" href="${esc(safeUrl(w.link))}" target="_blank" rel="noopener noreferrer">관련 링크</a>`:''}</div></article>`)}$('#workList').innerHTML=cards.length?cards.join(''):'<div class="empty">조건에 맞는 작업물이 없습니다.</div>'}
  async function addWork(){const title=$('#workTitle').value.trim(),file=$('#workFile').files[0];if(!title)return toast('작업물 제목을 입력해 주세요.');if(!file&&!$('#workLink').value.trim())return toast('파일이나 관련 링크 중 하나를 추가해 주세요.');const btn=$('#workAdd');setBusy(btn,true,file?'파일 업로드 중…':'저장 중…');let meta=null;try{if(file)meta=await withError(()=>Storage.uploadWorkFile(file),'작업물 파일 업로드');await withError(()=>DB.addWork({category:$('#workCategory').value,title,description:$('#workDescription').value.trim(),link:$('#workLink').value.trim(),file_path:meta?.path,file_name:file?.name,file_size:meta?.size,file_type:meta?.type}),'작업물 저장');$('#workTitle').value='';$('#workDescription').value='';$('#workLink').value='';$('#workFile').value='';await loadLab();toast('작업물을 저장했습니다.')}catch(e){if(meta?.path)await Storage.removePrivatePaths([meta.path]).catch(()=>{});throw e}finally{setBusy(btn,false)}}
  async function editWork(id){const w=state.works.find(x=>x.id===id);if(!w)return;const title=prompt('작업물 제목',w.title);if(title===null)return;const description=prompt('설명',w.description||'');if(description===null)return;const link=prompt('관련 링크(선택)',w.link||'');if(link===null)return;await withError(()=>DB.updateWork(id,{category:w.category,title,description,link}),'작업물 수정');await loadLab();toast('작업물을 수정했습니다.')}
  async function deleteWork(id){if(!confirm('작업물을 삭제할까요?'))return;const w=state.works.find(x=>x.id===id);await withError(()=>DB.deleteWork(id),'작업물 삭제');let cleanupFailed=false;if(w?.file_path)try{await Storage.removePrivatePaths([w.file_path])}catch(e){cleanupFailed=true;console.warn(e)}await loadLab();toast(cleanupFailed?'작업물은 삭제됐고 파일 정리는 다음 점검에서 다시 확인합니다.':'작업물을 삭제했습니다.')}
  function financeFilters(){return{query:$('#financeSearchName').value,date:$('#financeSearchDate').value,type:$('#financeSearchType').value,category:$('#financeSearchCategory').value}}
  let financeAnalysisType='expense';
  function renderFinanceAnalysis(month,income,expense){
    const type=financeAnalysisType,total=type==='expense'?expense:income,totals=new Map();
    month.filter(x=>x.tx_type===type).forEach(x=>{const name=x.category||'기타';totals.set(name,(totals.get(name)||0)+Number(x.amount))});
    const rows=[...totals].filter(([,value])=>value>0).sort((a,b)=>b[1]-a[1]),colors=['#406c59','#d2a86b','#829eb0','#bd817c','#8b8cb6','#9cb880','#bb9cba','#c0a26e','#778e8a'];
    let cursor=0;const segments=rows.map(([,value],i)=>{const start=cursor;cursor+=value/total*100;return `${colors[i%colors.length]} ${start}% ${cursor}%`});
    $('#financeAnalysisMonth').textContent=$('#financeMonthLabel').textContent;
    for(const [name,button] of [['expense','#financeAnalysisExpense'],['income','#financeAnalysisIncome']]){$(button).classList.toggle('active',name===type);$(button).setAttribute('aria-pressed',String(name===type))}
    $('#financeCategorySummary').innerHTML=rows.length?`<div class="finance-donut" role="img" aria-label="${type==='expense'?'지출':'수입'} 분류별 비율"><div><span>${type==='expense'?'총지출':'총수입'}</span><strong>${money(total)}</strong></div></div><div class="finance-breakdown">${rows.map(([name,value],i)=>{const ratio=value/total*100;return `<div class="finance-breakdown-row"><div><span class="finance-category-name"><i></i>${esc(name)}</span><strong>${money(value)}</strong></div><span>${ratio.toFixed(1)}%</span><b></b></div>`}).join('')}</div>`:`<p class="finance-analysis-empty">선택한 달의 ${type==='expense'?'지출':'수입'} 내역이 없습니다.</p>`;
    if(rows.length){const host=$('#financeCategorySummary');host.querySelector('.finance-donut').style.backgroundImage=`conic-gradient(${segments.join(',')})`;host.querySelectorAll('.finance-breakdown-row').forEach((el,i)=>{el.querySelector('i').style.backgroundColor=colors[i%colors.length];el.querySelector('b').style.width=`${rows[i][1]/total*100}%`;el.querySelector('b').style.backgroundColor=colors[i%colors.length]})}
  }
  function renderFinance(){const view=state.financeView,mk=`${view.getFullYear()}-${String(view.getMonth()+1).padStart(2,'0')}`,month=state.finance.filter(x=>x.tx_date?.startsWith(mk)),income=month.filter(x=>x.tx_type==='income').reduce((s,x)=>s+Number(x.amount),0),expense=month.filter(x=>x.tx_type==='expense').reduce((s,x)=>s+Number(x.amount),0),balance=Finance.currentBalance(state.finance,DB.today()).total;$('#financeMonthLabel').textContent=`${view.getFullYear()}년 ${view.getMonth()+1}월`;$('#financeBalance').textContent=money(balance);$('#financeIncome').textContent=money(income);$('#financeExpense').textContent=money(expense);$('#financeNet').textContent=money(income-expense);renderFinanceAnalysis(month,income,expense);const filters=financeFilters(),active=Object.values(filters).some(Boolean),rows=Finance.filterRows(month,filters);$('#financeSearchSummary').textContent=active?`검색 결과 ${rows.length}개`:`선택한 달 ${month.length}개`;$('#financeSearchToggle').textContent=active?'기록 검색 · 적용 중':'기록 검색';$('#transactionList').innerHTML=rows.length?rows.slice(0,80).map(x=>`<div class="transaction"><div class="transaction-copy"><time>${fmtShort(x.tx_date)}</time><strong>${esc(x.title)}</strong><small>${esc(x.tx_type==='balance'?'시작 잔액':x.category)}</small></div><span class="amount ${x.tx_type}">${x.tx_type==='income'?'+':x.tx_type==='expense'?'-':''}${money(x.amount)}</span><div class="transaction-actions"><button class="link-btn" data-edit-finance="${x.id}">수정</button><button class="link-btn danger" data-delete-finance="${x.id}" aria-label="가계부 기록 삭제">삭제</button></div></div>`).join(''):`<div class="empty" style="margin:10px">${month.length&&active?'조건에 맞는 가계부 기록이 없습니다.':'선택한 달의 가계부 기록이 없습니다.'}</div>`}
  function resetFinanceSearch(){$('#financeSearchName').value='';$('#financeSearchDate').value='';$('#financeSearchType').value='';$('#financeSearchCategory').value='';renderFinance();$('#financeSearchName').focus()}
  function moveFinanceMonth(delta){state.financeView=new Date(state.financeView.getFullYear(),state.financeView.getMonth()+delta,1);$('#financeSearchDate').value='';renderFinance()}
  async function addFinance(){const type=$('#financeType').value,title=$('#financeTitle').value.trim(),amount=Number($('#financeAmount').value.replace(/[^0-9]/g,'')),date=$('#financeDate').value||DB.today();if(!title)return toast(type==='balance'?'시작 잔액 이름을 입력해 주세요.':'내용을 입력해 주세요.');if(!Number.isFinite(amount)||amount<0||(!amount&&type!=='balance'))return toast('금액을 입력해 주세요.');await withError(()=>DB.addFinance({tx_type:type,title,amount,tx_date:date,category:type==='balance'?'시작 잔액':$('#financeCategory').value}),'가계부 저장');$('#financeTitle').value='';$('#financeAmount').value='';await loadLab();toast('가계부에 저장했습니다.')}
  async function editFinance(id){const x=state.finance.find(v=>v.id===id);if(!x)return;const title=prompt('내용',x.title);if(title===null)return;const amount=prompt('금액',String(x.amount));if(amount===null)return;const date=prompt('날짜 (YYYY-MM-DD)',x.tx_date);if(date===null)return;await withError(()=>DB.updateFinance(id,{tx_type:x.tx_type,title,amount:Number(amount.replace(/[^0-9]/g,'')),tx_date:date,category:x.category}),'가계부 수정');await loadLab();toast('가계부 기록을 수정했습니다.')}

  function publicationPayload(source,type){const title=type==='diary'?(source.title||'오늘의 일기'):type==='book'?(source.title||'독서록'):(source.title||'기록'),meta={category:source.category,mood:source.mood,tags:source.tags,entry_date:source.entry_date};if(type==='book')meta.author=bookMeta(source,'저자');return{title,body:source.body||'',meta}}
  function publicationBookAuthor(pub){if(pub?.source_type!=='book')return'';return pub.meta?.author||(pub.meta?.tags||[]).find(tag=>String(tag).startsWith('저자:'))?.slice(3)||''}
  function publicationMedia(pub){const saved=Array.isArray(pub?.meta?.public_media)?pub.meta.public_media:[],items=saved.map(item=>typeof item==='string'?{path:item,name:'공유 사진'}:{path:item?.path,name:item?.name||'공유 사진'}).filter(item=>item.path);if(pub?.cover_path&&!items.some(item=>item.path===pub.cover_path))items.unshift({path:pub.cover_path,name:'공유 사진'});return items.slice(0,6)}
  function publicationMediaPaths(pub){return [...new Set(publicationMedia(pub).map(item=>item.path))]}
  function openPublish(type,id){if(!cfg.PUBLIC_SHARING_ENABLED)return toast('광장 공유 기능을 사용할 수 없습니다.');if(!['record','diary','book'].includes(type))return toast('이 항목은 광장에 공유할 수 없습니다.');if(!ensureCommunityTerms())return;state.publishTarget={type,id};$('#publishAudience').value='public';$('#publishMedia').checked=true;openModal('publishModal')}
  async function publishCurrent(){if(!ensureCommunityTerms())return;const t=state.publishTarget;if(!t)return;const btn=$('#publishConfirm');setBusy(btn,true,'공유 준비 중…');const newPublicPaths=[];let oldPub=null;try{const source=await DB.getSource(t.type,t.id);oldPub=await DB.getPublicationForSource(t.type,t.id);const payload=publicationPayload(source,t.type),shareMedia=$('#publishMedia').checked,media=shareMedia?(source.record_media||[]).sort((a,b)=>a.sort_order-b.sort_order).slice(0,6):[];for(const item of media){const path=await Storage.copyPrivateToPublic(item.storage_path,item.original_name,t.type);newPublicPaths.push(path)}
      payload.meta.public_media=newPublicPaths.map((path,index)=>({path,name:media[index]?.original_name||`공유 사진 ${index+1}`}));payload.cover_path=newPublicPaths[0]||null;
      await DB.upsertPublication({source_type:t.type,source_id:t.id,audience:$('#publishAudience').value,title:payload.title,body:payload.body,meta:payload.meta,cover_path:payload.cover_path});const keep=new Set(newPublicPaths),oldPaths=[...publicationMediaPaths(oldPub),oldPub?.meta?.public_file_path].filter(Boolean);await Promise.allSettled([...new Set(oldPaths)].filter(path=>!keep.has(path)).map(path=>Storage.removePublic(path)));state.profile=await DB.ensureProfile();fillProfileUI();dismissModal('publishModal');await refreshCurrent();toast(newPublicPaths.length>1?`사진 ${newPublicPaths.length}장과 함께 광장에 공유했습니다.`:'광장에 공유했습니다. 원본은 개인 연구실에 그대로 남아 있습니다.')}catch(e){await Promise.allSettled(newPublicPaths.map(path=>Storage.removePublic(path)));toast(e?.message||'광장 공유에 실패했습니다.');console.error(e)}finally{setBusy(btn,false)}}
  async function unpublish(type,id){if(!confirm('광장 공유를 취소할까요? 개인 연구실 원본은 삭제되지 않습니다.'))return;const pub=await DB.getPublicationForSource(type,id);await withError(()=>DB.unpublish(type,id),'공유 취소');const paths=[...publicationMediaPaths(pub),pub?.meta?.public_file_path].filter(Boolean);await Promise.allSettled([...new Set(paths)].map(path=>Storage.removePublic(path)));await refreshCurrent();toast('광장에서 내렸습니다.')}
  async function refreshCurrent(){if(state.page==='records')await loadRecords();else if(state.page==='diary')await loadDiary();else if(state.page==='books')await loadBooks();else if(state.page==='square')await loadSquare();else if(state.page==='today')await loadToday()}

  async function loadSquare(){if(!cfg.COMMUNITY_ENABLED){$('#squareTabs').classList.add('hidden');$('#squareFeedback').classList.add('hidden');$('#squareDiscover').classList.remove('hidden');$('#squareFeed').innerHTML='<div class="stage-placeholder"><strong>광장을 준비하고 있습니다.</strong></div>';return}$('#squareTabs').classList.remove('hidden');if(state.squareTab==='feedback')return loadFeatures();const rows=await withError(()=>DB.feed(state.squareTab,state.squareCategory),'광장 불러오기');renderFeed(rows)}
  function switchSquare(tab){state.squareTab=tab;$$('#squareTabs [data-square]').forEach(b=>b.classList.toggle('active',b.dataset.square===tab));$('#squareDiscover').classList.toggle('hidden',tab==='feedback');$('#squareFeedback').classList.toggle('hidden',tab!=='feedback');$('#communityComposer').classList.toggle('hidden',tab==='feedback');loadSquare().catch(()=>{})}
  function renderFeed(rows){
    if(!rows.length){$('#squareFeed').innerHTML=`<div class="empty" style="grid-column:1/-1">${state.squareTab==='following'?'팔로우한 연구실의 새 공유가 아직 없습니다.':'아직 광장에 공유된 내용이 없습니다.'}</div>`;return}
    const host=$('#squareFeed');host.innerHTML=rows.map(p=>{const media=publicationMedia(p),bookAuthor=publicationBookAuthor(p),own=p.user_id===DB.user().id,profileUrl=`./public.html?slug=${encodeURIComponent(p.slug)}`,title=p.source_type==='community'?'':`<h3>${esc(p.title)}</h3>`,gallery=media.length?`<div class="pub-gallery" data-count="${media.length}" data-lightbox-gallery>${media.map((item,index)=>{const url=Storage.publicUrl(item.path);return `<button type="button" data-lightbox="${esc(url)}" aria-label="공유 사진 ${index+1} 크게 보기"><img src="${esc(url)}" alt="${esc(item.name||`공유 사진 ${index+1}`)}" loading="lazy"></button>`}).join('')}</div>`:'';return `<article class="pub-card" data-publication-card="${p.id}">${gallery}<div class="pub-body"><div class="pub-author">${avatarMarkup(p.display_name,p.avatar_path,'',p.avatar_frame_tier,p.avatar_frame_color)}<div><strong><a href="${esc(profileUrl)}">${esc(p.lab_name)}</a></strong><span>${esc(p.display_name)} · ${fmtTime(p.published_at)}</span></div>${!own?`<button class="follow-btn ${p.following_author?'on':''}" data-follow="${p.user_id}" data-on="${p.following_author}">${p.following_author?'팔로잉':'팔로우'}</button>`:''}</div><div class="pub-meta"><span class="chip">${sourceLabel(p.source_type)}</span>${bookAuthor?`<span class="pub-book-author">${esc(bookAuthor)} 지음</span>`:''}</div>${title}${collapsibleCopy(p.body)}<div class="pub-actions"><button class="like-button ${p.liked_by_me?'on':''}" data-like="${p.id}" data-on="${p.liked_by_me}" aria-label="좋아요" aria-pressed="${p.liked_by_me}"><svg class="like-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20.2 4.8 13.4a5.2 5.2 0 0 1-.3-7.1 4.8 4.8 0 0 1 7.5.6 4.8 4.8 0 0 1 7.5-.6 5.2 5.2 0 0 1-.3 7.1Z"/></svg><span class="count">${p.like_count}</span></button><button class="comment-toggle" data-comments="${p.id}" aria-label="댓글 ${p.comment_count}개 보기" aria-expanded="false"><svg class="comment-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.2c0 4.1-3.6 7.3-8 7.3-1.1 0-2.2-.2-3.1-.6L4 20l1.3-4C4.5 14.7 4 13 4 11.2 4 7.1 7.6 4 12 4s8 3.1 8 7.2Z"/></svg><span class="count">${p.comment_count}</span><svg class="comment-arrow" viewBox="0 0 20 20" aria-hidden="true"><path d="m6 8 4 4 4-4"/></svg></button><button class="share-button" data-copy-link="${esc(profileUrl)}"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M7 6.5 10 3l3 3.5M10 3v9M4 9v6h12V9"/></svg><span>공유</span></button>${own?`<button class="danger unpublish-button" data-unpublish="${p.source_type}:${p.source_id}">내리기</button>`:`<button class="moderation-btn" data-report-type="publication" data-report-id="${p.id}" data-report-user="${p.user_id}" data-report-label="${esc(p.lab_name)}의 게시물">신고</button><button class="moderation-btn danger" data-block-user="${p.user_id}" data-block-name="${esc(p.display_name)}">차단</button>`}</div><section class="inline-comments hidden" data-comment-panel="${p.id}"><div class="inline-comment-list"></div><div class="comment-compose"><input class="input" data-comment-input="${p.id}" maxlength="2000" placeholder="댓글을 입력하세요"><button class="btn primary small" data-submit-comment="${p.id}">등록</button></div></section></div></article>`}).join('');activateCollapsibleText(host)
  }
  async function toggleFollow(userId,on){if(!ensureCommunityTerms())return;await withError(()=>DB.toggleFollow(userId,on),'팔로우');await loadSquare()}
  async function toggleLike(pubId,on){if(!ensureCommunityTerms())return;await withError(()=>DB.toggleLike(pubId,on),'좋아요');await loadSquare()}
  async function openComments(pubId){const panel=$(`[data-comment-panel="${pubId}"]`),button=$(`[data-comments="${pubId}"]`);if(!panel)return;const opening=panel.classList.contains('hidden');panel.classList.toggle('hidden',!opening);button?.setAttribute('aria-expanded',String(opening));if(!opening)return;const rows=await withError(()=>DB.comments(pubId),'댓글 불러오기');state.commentThreads.set(pubId,rows);renderComments(pubId)}
  function commentActions(c,pubId){return `<button class="link-btn" data-reply-comment="${c.id}" data-reply-publication="${pubId}" data-reply-name="${esc(c.display_name)}">답글</button>${c.user_id===DB.user().id?`<button class="link-btn danger" data-delete-comment="${c.id}" data-comment-publication="${pubId}">삭제</button>`:`<button class="link-btn" data-report-type="comment" data-report-id="${c.id}" data-report-user="${c.user_id}" data-report-label="${esc(c.display_name)}님의 댓글">신고</button>`}`}
  function renderComment(c,replies=[],pubId){return `<div class="inline-comment ${c.parent_id?'reply':''}" data-comment-id="${c.id}">${avatarMarkup(c.display_name,c.avatar_path,'comment-avatar',c.avatar_frame_tier,c.avatar_frame_color)}<div class="comment-copy"><strong>${esc(c.display_name)}</strong><span>${fmtTime(c.created_at)}</span><p>${c.parent_display_name?`<b>@${esc(c.parent_display_name)}</b> `:''}${esc(c.body)}</p><div class="comment-actions">${commentActions(c,pubId)}</div></div></div>${replies.map(r=>renderComment(r,[],pubId)).join('')}`}
  function renderComments(pubId){const panel=$(`[data-comment-panel="${pubId}"]`),rows=state.commentThreads.get(pubId)||[];if(!panel)return;const roots=rows.filter(c=>!c.parent_id),children=new Map();rows.filter(c=>c.parent_id).forEach(c=>children.set(c.parent_id,[...(children.get(c.parent_id)||[]),c]));panel.querySelector('.inline-comment-list').innerHTML=roots.length?roots.map(c=>renderComment(c,children.get(c.id)||[],pubId)).join(''):'<div class="empty">첫 댓글을 남겨보세요.</div>'}
  async function refreshCommentThread(pubId){const rows=await DB.comments(pubId);state.commentThreads.set(pubId,rows);renderComments(pubId);const count=$(`[data-comments="${pubId}"] .count`);if(count)count.textContent=String(rows.length);return rows}
  async function submitComment(pubId){if(!ensureCommunityTerms())return;const input=$(`[data-comment-input="${pubId}"]`),body=input?.value.trim();if(!body)return;const parent=state.replyTo?.publicationId===pubId?state.replyTo.commentId:null;await withError(()=>DB.addComment(pubId,body,parent),'댓글 등록');input.value='';input.placeholder='댓글을 입력하세요';state.replyTo=null;await refreshCommentThread(pubId);toast(parent?'답글을 남겼습니다.':'댓글을 남겼습니다.')}
  async function addCommunityPost(){if(!ensureCommunityTerms())return;const input=$('#communityPostBody'),body=input.value.trim();if(!body)return toast('자유글 내용을 입력해 주세요.');const btn=$('#communityPostSubmit');setBusy(btn,true,'올리는 중…');try{await withError(()=>DB.addCommunityPost(body),'자유글 등록');input.value='';$('#communityComposer').open=false;state.squareCategory='community';$$('[data-square-category]').forEach(x=>x.classList.toggle('active',x.dataset.squareCategory==='community'));await loadSquare();toast('자유글을 광장에 올렸습니다.')}finally{setBusy(btn,false)}}
  async function loadFeatures(){const rows=await withError(()=>DB.features(),'개선 제안 불러오기');$('#featureList').innerHTML=rows.length?rows.map(f=>`<article class="feature-card"><button class="vote-btn ${f.voted_by_me?'on':''}" data-vote="${f.id}" data-on="${f.voted_by_me}"><strong>△</strong><span>${f.vote_count}</span></button><div><h4>${esc(f.title)}</h4><p>${esc(f.body||'')}</p><span class="status-badge ${f.status==='done'?'done':''}">${featureStatus(f.status)}</span><span class="muted" style="font-size:8px;margin-left:6px">${esc(f.display_name)} · ${fmtTime(f.created_at)}</span></div></article>`).join(''):'<div class="empty">첫 개선 제안을 남겨보세요.</div>'}
