  function openReport(type,id,userId,label='광장 콘텐츠'){state.reportTarget={type,id,userId,label};$('#reportTargetLabel').textContent=`${label}을 신고합니다. 신고 내용은 공개되지 않습니다.`;$('#reportReason').value='spam';$('#reportDetails').value='';$('#reportBlockUser').checked=false;$('#reportBlockRow').classList.toggle('hidden',!userId||userId===DB.user().id);openModal('reportModal')}
