  async function saveProfile(){const btn=$('#profileSave'),tz=$('#settingsTimezone').value.trim(),theme=$('#settingsTheme').value,oldPath=state.profile?.avatar_path||null;let uploadedPath=null,profileSaved=false;if(!validTimezone(tz))return toast('올바른 IANA 시간대를 입력해 주세요. 예: Asia/Seoul');setBusy(btn,true,'저장 중…');try{if(state.profilePhotoFile)uploadedPath=await withError(()=>Storage.uploadProfileImage(state.profilePhotoFile),'프로필 사진 업로드');const avatarPath=uploadedPath||(state.profilePhotoRemove?null:oldPath);state.profile=await withError(()=>DB.updateProfile({display_name:$('#settingsName').value,lab_name:$('#settingsLabName').value,slug:$('#settingsSlug').value,bio:$('#settingsBio').value,avatar_path:avatarPath,avatar_frame_tier:state.frameDraftTier,avatar_frame_color:state.frameDraftColor}),'프로필 저장');profileSaved=true;localStorage.setItem(`lab:timezone:${DB.user().id}`,tz);localStorage.setItem(`lab:theme:${DB.user().id}`,theme);applyTheme(theme);if(oldPath&&oldPath!==avatarPath)Storage.removePublic(oldPath).catch(error=>console.warn('이전 프로필 사진 정리 실패',error));clearProfilePhotoDraft();fillProfileUI();toast('프로필과 화면 설정을 저장했습니다.')}catch(error){if(uploadedPath&&!profileSaved)await Storage.removePublic(uploadedPath).catch(()=>{});throw error}finally{setBusy(btn,false)}}
  async function togglePublicProfile(){if(!cfg.PUBLIC_SHARING_ENABLED)return toast('공개 포트폴리오는 이후 단계에서 활성화할 예정입니다.');const next=!state.profile.public_profile;if(!next){const pubs=await DB.listOwnPublications();if(pubs.length)return toast('공개 프로필을 끄려면 먼저 공유 중인 항목을 광장에서 내려주세요.')}state.profile=await withError(()=>DB.updateProfile({public_profile:next}),'공개 프로필 설정');fillProfileUI();toast(next?'공개 연구실 프로필을 켰습니다.':'공개 연구실 프로필을 껐습니다.')}
  async function exportData(){const btn=$('#exportData');setBusy(btn,true,'준비 중…');try{const data=await withError(()=>DB.exportData(),'데이터 내보내기'),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`personal-lab-export-${DB.today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('내 데이터를 JSON으로 내보냈습니다.')}finally{setBusy(btn,false)}}
  async function restoreDataFile(event){const input=event.currentTarget,file=input.files?.[0];if(!file)return;let serverAttempt=false;try{if(file.size>10*1024*1024)throw new Error('복원 파일은 10MB 이하여야 합니다.');let backup;try{backup=JSON.parse(await file.text())}catch{throw new Error('JSON 파일을 읽을 수 없습니다.')}if(!backup||backup.version!==3||!Array.isArray(backup.profiles)||backup.profiles.length!==1)throw new Error('지원하는 하루를 담다 백업 파일이 아닙니다.');if(backup.profiles[0]?.id!==DB.user().id)throw new Error('현재 로그인한 계정에서 만든 백업만 복원할 수 있습니다.');if(!confirm('백업의 개인 생활 데이터를 현재 계정에 합칠까요?\n\n현재 데이터는 삭제하지 않습니다. 첨부파일과 광장 활동은 자동 복원하지 않습니다.'))return;serverAttempt=true;const result=await withError(()=>DB.restoreData(backup),'데이터 복원');toast(`${Number(result.restored||0)}개 항목을 확인해 복원했습니다.`);await refreshCurrent()}catch(e){if(!serverAttempt)toast(e.message||'데이터 복원에 실패했습니다.')}finally{input.value=''}}

