  async function boot(){bind();history.replaceState({haruPage:'today'},'',location.href);window.addEventListener('popstate',event=>{$$('.modal-backdrop.show').forEach(m=>hideModal(m.id));closeLightbox();const page=event.state?.haruPage||'today';if(page!==state.page)void route(page,{silent:true,fromHistory:true})});updateNetwork();if(DB.initError){$('#authMessage').textContent=DB.initError;$('#authShell').classList.remove('hidden');return}try{const session=await DB.getSession();if(session)await enterApp();else $('#authShell').classList.remove('hidden')}catch(e){console.error(e);$('#authMessage').textContent='초기 연결에 실패했습니다. 네트워크 또는 Supabase 설정을 확인해 주세요.';$('#authShell').classList.remove('hidden')}}
  function showPendingProjectFiles(){const inp=$('#projectProcessFiles'),host=$('#projectPendingFileList');if(!inp||!host)return;const files=[...(inp.files||[])];host.innerHTML=files.length?`<small class="muted">저장할 파일 ${files.length}개</small>${files.map(f=>`<div class="file-row pending"><span>${esc(f.name)}</span><small>저장 대기</small></div>`).join('')}`:''}
  async function uploadPendingProjectFiles(project=state.projectEdit){const p=project,inp=$('#projectProcessFiles');if(!p||!inp?.files?.length)return;await Storage.uploadProjectFiles(p.id,[...inp.files]);inp.value='';showPendingProjectFiles();toast('과정 파일을 저장했습니다.')}
  document.addEventListener('click',e=>{if(e.target.closest('[data-open-project]')&&!$('#projectProcessFiles')){const save=$('#projectDetailSave');if(save){const label=document.createElement('label');label.className='photo-picker';label.innerHTML='과정 파일 추가 · 파일당 최대 20MB<input id="projectProcessFiles" type="file" multiple accept="image/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.txt,.hwp,.hwpx">';const pending=document.createElement('div');pending.id='projectPendingFileList';pending.className='file-list pending-file-list';save.parentElement.before(label);label.after(pending);label.querySelector('input').addEventListener('change',showPendingProjectFiles)}} });
  async function showProjectFiles(){const p=state.projectEdit;if(!p)return;const inp=$('#projectProcessFiles');if(!inp)return;let host=$('#projectProcessFileList');if(!host){host=document.createElement('div');host.id='projectProcessFileList';host.className='file-list';inp.closest('label').after(host)}try{const rows=await DB.listProjectFiles(p.id);host.innerHTML=rows.length?rows.map(f=>`<div class="file-row"><span>${esc(f.original_name)}</span><button class="link-btn" data-download-project-file="${esc(f.storage_path)}" data-project-name="${esc(f.original_name)}">열기</button></div>`).join(''):'<small class="muted">저장된 과정 파일이 없습니다.</small>'}catch{host.innerHTML='<small class="muted">과정 파일 목록을 불러오지 못했습니다.</small>'}}
  document.addEventListener('click',e=>{if(e.target.closest('[data-open-project]'))setTimeout(()=>showProjectFiles(),300);const dl=e.target.closest('[data-download-project-file]');if(dl)Storage.downloadPrivate(dl.dataset.downloadProjectFile,dl.dataset.projectName).catch(err=>toast(err.message))});
  boot();
